def test_wall_timeout_kills_session_escaping_descendants(lab: IsolationLab) -> None:
    """后代 setsid 仍在同 cgroup；TERM 不退出时墙钟路径杀死实际容器整树。"""
    box = lab.worker("agent", "tree")
    spawn = box.await_event("spawn")
    descendant = spawn["grandchild_pid"]
    code = (
        "import os,json; from pathlib import Path; "
        f"print(json.dumps({{'session':os.getsid({descendant}), 'group':Path('/proc/{descendant}/cgroup').read_text()}}))"
    )
    state = json.loads(docker("exec", box.identity, "python", "-c", code))
    assert state["session"] == descendant and state["group"].strip() == "0::/"
    docker("kill", "--signal", "TERM", box.identity)
    assert box.inspect()["State"]["Running"]
    started = monotonic()
    with pytest.raises(IsolationError, match="wall_timeout_container_stopped"):
        box.wait(0.3)
    assert monotonic() - started < 10
    box.require_stopped()
    with pytest.raises(IsolationError):
        docker("top", box.identity)
    with pytest.raises(IsolationError, match="cache_not_empty"):
        box.cleanup_evidence()
    assert box.cache_action("clean") == {"empty": True}
    assert box.cleanup_evidence()["scope"] == "local_probe_only"


def test_real_cgroup_oom_does_not_kill_sibling_worker(lab: IsolationLab) -> None:
    """真实超内存触发 oom_kill 与 SIGKILL，另一容器内的 worker 继续运行。"""
    sibling = lab.worker("agent", "tree")
    sibling.await_event("spawn")
    box = lab.worker("agent", "oom")
    assert box.wait(15) == 1
    summary = next(event for event in box.events() if "oom_kill" in event)
    assert summary["oom_kill"] >= 1 and summary["exitcode"] == -9
    assert sibling.inspect()["State"]["Running"]
    sibling.stop()


def test_cleanup_needs_stopped_process_and_verifiable_empty_cache(lab: IsolationLab) -> None:
    """活进程、残留缓存、缓存无法访问均不构成清理完成；symlink 不跟随。"""
    box = lab.worker("normalizer", "tree")
    box.await_event("spawn")
    with pytest.raises(IsolationError, match="process_still_present"):
        box.cleanup_evidence()
    box.stop()
    with pytest.raises(IsolationError, match="cache_not_empty"):
        box.cleanup_evidence()
    box.cache_action("lock")
    try:
        with pytest.raises(IsolationError, match="docker_failed"):
            box.cleanup_evidence()
    finally:
        box.cache_action("unlock")
    assert box.cache_action("clean") == {"empty": True}
    assert box.cleanup_evidence()["cache_empty"] is True
